using Microsoft.AspNetCore.Diagnostics;using SchoolERP.Api.ErrorHandling;using SchoolERP.Api.Logging;namespace SchoolERP.Api.Middleware;public sealed class GlobalExceptionHandler(IExceptionMapper mapper,ILogger<GlobalExceptionHandler> logger):IExceptionHandler{public async ValueTask<bool>TryHandleAsync(HttpContext c,Exception ex,CancellationToken ct){if(ex is OperationCanceledException&&c.RequestAborted.IsCancellationRequested){logger.LogInformation("Request aborted by client. RequestId {RequestId}",c.TraceIdentifier);return false;}if(c.Response.HasStarted){logger.LogError(LoggingEventIds.Infrastructure.UnhandledException,ex,"Exception occurred after response started. RequestId {RequestId}",c.TraceIdentifier);return false;}var d=mapper.Map(ex);if(d.LogLevel==LogLevel.Error)logger.LogError(LoggingEventIds.Infrastructure.UnhandledException,ex,"Request failed with {ErrorCode}. RequestId {RequestId}",d.Code,c.TraceIdentifier);else if(d.LogLevel==LogLevel.Warning)logger.LogWarning("Request failed with {ErrorCode}. RequestId {RequestId}",d.Code,c.TraceIdentifier);else logger.LogInformation("Request failed with {ErrorCode}. RequestId {RequestId}",d.Code,c.TraceIdentifier);await ApiErrorWriter.WriteAsync(c,ApiErrorWriter.Create(c,d.Code,d.Message,d.StatusCode,d.Errors),ct);return true;}}
